INSERT INTO public.restaurants (id,owner_id,slug,name,description,cuisine,logo_url,cover_image_url,price_range,currency,delivery_fee,min_order_amount,delivery_estimate_minutes,approval_status,is_verified,is_demo,is_accepting_orders,avg_rating,rating_count) VALUES
('d0000000-0000-4000-8000-000000000001','5338d47c-f75f-4748-ab52-d094d79ed2e4','mamas-kota-spot','Mama''s Kota Spot','Legendary Soweto-style kotas stacked with chips, polony, cheese and atchar. A township classic done properly.','South African','https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=400&q=80','https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=1200&q=80','R','ZAR',25,0,30,'approved',true,true,true,4.7,132),
('d0000000-0000-4000-8000-000000000002','5338d47c-f75f-4748-ab52-d094d79ed2e4','the-curry-leaf','The Curry Leaf','Authentic Durban curries and bunny chows — slow-cooked, fiery, and served with fresh sambals.','Indian','https://images.unsplash.com/photo-1585937421612-70a008356fbe?auto=format&fit=crop&w=400&q=80','https://images.unsplash.com/photo-1565557623262-b51c2513a641?auto=format&fit=crop&w=1200&q=80','RR','ZAR',35,80,40,'approved',true,true,true,4.8,214),
('d0000000-0000-4000-8000-000000000003','5338d47c-f75f-4748-ab52-d094d79ed2e4','braai-and-co','Braai & Co','Flame-grilled boerewors, chops and chicken straight off the coals, with pap, chakalaka and all the sides.','Braai & Grill','https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=400&q=80','https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1200&q=80','RR','ZAR',30,100,45,'approved',true,true,true,4.6,98)
